#include "FaultInjectionEngine.h"
namespace dnxr {
const char* toString(HILFaultType f){switch(f){case HILFaultType::SignalLoss:return "signal loss";case HILFaultType::ExtremeNoise:return "extreme noise";case HILFaultType::CalibrationDrift:return "calibration drift";case HILFaultType::VestibularOverload:return "vestibular overload";case HILFaultType::RejectedStimulus:return "rejected stimulus";case HILFaultType::StaleWatchdogSubsystem:return "stale watchdog subsystem";case HILFaultType::LatencyOverrun:return "latency overrun";case HILFaultType::EmergencyStop:return "emergency stop";case HILFaultType::ReplayAttack:return "replay attack";case HILFaultType::PacketCorruption:return "packet corruption";case HILFaultType::PhantomDisconnect:return "phantom disconnect";case HILFaultType::TimingJitter:return "timing jitter";case HILFaultType::FullDiveDesynchronization:return "full-dive desynchronization";}return "unknown";}
void FaultInjectionEngine::inject(HILFaultEvent event){events_.push_back(event);} std::vector<HILFaultEvent> FaultInjectionEngine::events() const{return events_;} bool FaultInjectionEngine::hasFault(HILFaultType type) const{for(const auto& e:events_) if(e.type==type) return true; return false;} void FaultInjectionEngine::clear(){events_.clear();}
}
